  if (checksNode === null) return <span data-testid="falsifying-check-text" data-check-id={check.id}>{label}</span>
  return (
    <AppLink
      href={checksNode.href}
      onNavigate={onNavigate}
      data-testid="falsifying-check-link"
      data-check-id={check.id}
      data-check-index={executed === -1 ? undefined : executed}
      title={`The executed check and its log are shown on ${checksNode.label}`}
    >
      {label} (on {checksNode.label}{where})
    </AppLink>
  )
}

/**
 * The evidence a 1.1.0 completion carries (PRD_PORTABLE_WORKFLOW 4.6): what no executed check covers, the check that would
 * fail if the implementation were wrong, and one assumption to verify independently. A 1.0.0 completion serves all three
 * as null, which is stated rather than shown as empty.
 */
function CompletionEvidence({ completion, worker, result, checksNode, onNavigate }: {
  completion: Completion
  worker: RunInputWorker
  result: Resource<WorkerResult>
  checksNode: CheckTarget | null
  onNavigate: (pathname: string) => void
}) {
  const { untested, falsifying_check: falsifying, verify_yourself: verify } = completion
  if (completion.status === 'question') {
    return (
      <p className="projects-muted" data-testid="completion-evidence-question">
        No completion evidence yet: the worker ended its turn with a question, listed below with its answer when there is one.
      </p>
    )
  }
  if (untested === null && falsifying === null && verify === null) {
    return (
      <p className="projects-muted" data-testid="completion-evidence-none">
        Completion evidence was not recorded for this run: its completion predates the untested, falsifying-check and verify-yourself fields.
      </p>
    )
  }
  return (
    <dl className="projects-facts completion-evidence" data-testid="completion-evidence">
      <div data-testid="evidence-untested">
        <dt>Untested</dt>
        <dd>
          {untested === null ? <span className="projects-muted">Not recorded</span>
            : untested.length === 0 ? <span className="projects-muted">Nothing: the worker names no behaviour outside its executed checks.</span>
              : <ul className="evidence-list">{untested.map((item, index) => <li key={index}>{item}</li>)}</ul>}
        </dd>
      </div>
      <div data-testid="evidence-falsifying-check">
        <dt>Falsifying check</dt>
        <dd>
          {falsifying === null || falsifying === ''
            ? <span className="projects-muted">Not recorded</span>
            : <FalsifyingCheck value={falsifying} worker={worker} result={result} checksNode={checksNode} onNavigate={onNavigate} />}
        </dd>
      </div>
      <div data-testid="evidence-verify-yourself">
        <dt>Verify yourself</dt>
        <dd>{verify === null || verify === '' ? <span className="projects-muted">Not recorded</span> : verify}</dd>
      </div>
    </dl>
  )
}

/** The questions the worker asked mid-run, with the operator's answers and times; an unanswered one is waiting on the operator. */
export function WorkerQuestions({ questions }: { questions: RunInputWorker['questions'] }) {
  const waiting = questions.filter(question => question.answer === null).length
  return (
    <section className="evidence-section" aria-labelledby="worker-questions-title" data-testid="worker-questions">
      <h4 id="worker-questions-title">Questions to the operator</h4>
      {questions.length === 0 ? (
        <p className="projects-muted" data-testid="worker-questions-none">No questions were recorded for this worker.</p>
      ) : (
        <>
          {waiting > 0 && (
            <p className="projects-notice" role="status" data-testid="worker-questions-waiting">
              {waiting === 1 ? 'One question is' : `${waiting} questions are`} waiting on the operator. Answers are given through the workflow CLI (<code>workflow answer</code>), not this viewer; the worker's deadline is paused meanwhile.
            </p>

      // The failed run was pinned before the setting existed and never reviewed: the export records null, never a guess.
      reviewer_transport: runId === RUN_BLOCKED ? 'print' : runId === RUN_FAILED ? null : 'native',
    },
    setup: [{ argv: ['npm', 'ci'], command: 'npm ci', timeout_seconds: 600 }],
    max_verification_attempts: 3,
    failure_drill: runId === RUN_FAILED ? { node_id: 'adapter', phase: 'worker', attempt: 1 } : null,
    workers: { ui: rawWorker('ui', runId, leak, requestedAt), adapter: rawWorker('adapter', runId, leak, requestedAt) },
  }
}

/** The guarded run's 1.5.0 inputs section: decisions, the accepted challenge, completion evidence and questions. */
function guardedInputsSection(leak: string): RawInputsSection {
  const ui = rawLaneWorker('ui', RUN_GUARDED, leak, T1)
  const adapter = rawLaneWorker('adapter', RUN_GUARDED, leak, T1)
  return {
    feature: GUARDED_FEATURE_NAME, policy_version: '1.2.0', base_commit: BASE_COMMIT,
    source_branch: sourceBranch(RUN_GUARDED, GUARDED_WORKFLOW_ID),
    mode: 'automatic',
    automatic: { finish: 'verified-feature-branch', permission_mode: 'bypassPermissions', worker_timeout_seconds: 7200, review_timeout_seconds: 1800, reviewer_transport: 'print' },
    setup: [{ argv: ['npm', 'ci'], command: 'npm ci', timeout_seconds: 600 }],
    max_verification_attempts: 3,
    failure_drill: { node_id: 'adapter', phase: 'worker', attempt: 1 },
    selected_workers: [...TWO_LANES],
    excluded_workers: [],
    workers: {
      ui: {
        ...ui,
        completion: {
          status: 'completed', summary: GUARDED_UI_SUMMARY, open_assumptions: [UI_ASSUMPTION],
          untested: GUARDED_UNTESTED, falsifying_check: GUARDED_FALSIFYING_CHECK, verify_yourself: GUARDED_VERIFY_YOURSELF,
        },
        handoff: { summary: GUARDED_UI_SUMMARY, open_assumptions: [UI_ASSUMPTION] },
        questions: GUARDED_QUESTIONS.ui,
      },
      adapter: {
        ...adapter,
        // The worker is in its fix turn and ended it with a question: no evidence yet, and its stop is not confirmed.
        completion: { status: 'question', summary: GUARDED_ADAPTER_SUMMARY, open_assumptions: [], untested: null, falsifying_check: null, verify_yourself: null },
        handoff: { summary: ADAPTER_COMPLETION_SUMMARY, open_assumptions: [] },
        stop: { stopped: false, confirmed_at: null },
        questions: GUARDED_QUESTIONS.adapter,
      },
    },
    decisions: GUARDED_DECISIONS,
    challenge: {
      status: 'accepted', attempt: 2, session_id: CHALLENGE_SESSION,
      pinned: { tasks_sha256: sha256('tasks'), decisions_sha256: sha256(GUARDED_DECISIONS), prd_sha256: sha256('prd') },
      concerns: [
        { severity: 'P2', kind: 'complexity', message: CHALLENGE_P2, consequence: CHALLENGE_P2_CONSEQUENCE },
        { severity: 'P1', kind: 'assumption', message: CHALLENGE_P1, consequence: CHALLENGE_P1_CONSEQUENCE },
      ],
      simpler_alternative: CHALLENGE_ALTERNATIVE, cheap_experiment: CHALLENGE_EXPERIMENT,
      accepted_reason: CHALLENGE_ACCEPTED_REASON, decided_at: CHALLENGE_DECIDED_AT, attempts: 2,
    },
  }
}

// ---- Projections onto the contract (what the mocks serve) ----------------------------------------------

/** The lanes (in policy order) whose task text contains the quote verbatim; the same rule the adapter applies. */
function lanesQuoting(requirement: string | null, tasks: Record<string, string>): string[] {
  if (requirement === null) return []
  return Object.keys(tasks).filter(lane => tasks[lane].includes(requirement))
}

/**
 * The review projection at contract 1.4.0. A section without `reviewers` (exports before 1.4.0) is one reviewer named
 * `review`: the adapter fills a one-entry list from the section itself and tags every finding with that id, so the viewer
 * has a single code path. The combined `reviewer` identity stays what the review node names (the first reviewer's session).
 */
function projectReview(runId: string, section: RawReviewSection, tasks: Record<string, string>): ReviewResult {
  const link = (finding: RawFinding, reviewer: string) => ({ ...finding, reviewer: finding.reviewer ?? reviewer, requirement_found_in: lanesQuoting(finding.requirement, tasks) })
  const reviewers: RawReviewer[] = section.reviewers ?? [{
    reviewer_id: DEFAULT_REVIEWER_ID, transport: section.transport, session_id: section.reviewer_session_id, verdict: section.verdict,
    findings: section.findings, launched_at: null, accepted_at: section.reviewed_at, status: section.verdict === 'approved' ? 'accepted' : 'blocked',
  }]
